'use client';

import { useId, useLayoutEffect, useRef, useState, type ReactNode } from 'react';
import { motion, useReducedMotion } from 'motion/react';
import './settings-sidebar.css';

export interface SettingsSidebarItem {
  /** Unique application-owned key across all groups. */
  value: string;
  label: string;
  icon?: ReactNode;
  trailing?: ReactNode;
  disabled?: boolean;
  /** ID of the caller's content region, if it has one. */
  controls?: string;
}

export interface SettingsSidebarGroup {
  id: string;
  label: string;
  items: readonly SettingsSidebarItem[];
}

export interface SettingsSidebarProps {
  groups: readonly SettingsSidebarGroup[];
  value: string;
  onValueChange: (value: string) => void;
  label?: string;
  header?: ReactNode;
  footer?: ReactNode;
  disabled?: boolean;
  className?: string;
}

/** In-page settings navigation. The caller owns selection, content, and persistence. */
export function SettingsSidebar({ groups, value, onValueChange, label = 'Settings', header,
  footer, disabled = false, className = '' }: SettingsSidebarProps) {
  const id = useId();
  const reduced = useReducedMotion();
  const bodyRef = useRef<HTMLDivElement>(null);
  const buttons = useRef(new Map<string, HTMLButtonElement>());
  const [hovered, setHovered] = useState<string | null>(null);
  const [surface, setSurface] = useState<{ x: number; y: number; width: number; height: number } | null>(null);
  const hoverEnabled = !disabled && hovered !== null && hovered !== value &&
    groups.some(group => group.items.some(item => item.value === hovered && !item.disabled));

  useLayoutEffect(() => {
    const body = bodyRef.current;
    const button = hovered === null ? undefined : buttons.current.get(hovered);
    if (!body || !button) return;
    const measure = () => {
      const bounds = button.getBoundingClientRect();
      const parent = body.getBoundingClientRect();
      const next = { x: bounds.left - parent.left, y: bounds.top - parent.top, width: bounds.width, height: bounds.height };
      setSurface(old => old && Object.keys(next).every(key => old[key as keyof typeof next] === next[key as keyof typeof next]) ? old : next);
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(body);
    observer.observe(button);
    return () => observer.disconnect();
  }, [hovered, groups]);

  return <nav className={`mf-settings-sidebar ${className}`} aria-label={label} data-reduced-motion={reduced || undefined}>
    {header && <div className="mf-settings-sidebar__header">{header}</div>}
    <div className="mf-settings-sidebar__scroll">
      <div className="mf-settings-sidebar__body" ref={bodyRef} onPointerLeave={() => setHovered(null)}>
        {surface && <motion.span aria-hidden="true" className="mf-settings-sidebar__hover" initial={false}
          animate={{ ...surface, opacity: hoverEnabled ? 1 : 0 }}
          transition={reduced ? { duration: 0 } : { type: 'spring', stiffness: 500, damping: 40, opacity: { duration: .2, ease: [.25, .1, .25, 1] } }}/>} 
        {groups.map(group => <section className="mf-settings-sidebar__group" key={group.id} aria-labelledby={`${id}-${group.id}`}>
          <h3 className="mf-settings-sidebar__group-label" id={`${id}-${group.id}`}>{group.label}</h3>
          <ul className="mf-settings-sidebar__items">
            {group.items.map(item => <li className="mf-settings-sidebar__item" key={item.value}
              onPointerEnter={event => setHovered(event.pointerType !== 'touch' && !disabled && !item.disabled ? item.value : null)}
              onPointerLeave={() => setHovered(null)}>
              <button ref={node => { if (node) buttons.current.set(item.value, node); else buttons.current.delete(item.value); }}
                type="button" className="mf-settings-sidebar__button" data-value={item.value}
                aria-current={value === item.value ? 'page' : undefined} aria-controls={item.controls}
                disabled={disabled || item.disabled}
                onClick={() => { if (item.value !== value) onValueChange(item.value); }}>
                {item.icon && <span className="mf-settings-sidebar__icon" aria-hidden="true">{item.icon}</span>}
                <span className="mf-settings-sidebar__label">{item.label}</span>
                {item.trailing && <span className="mf-settings-sidebar__trailing">{item.trailing}</span>}
              </button>
            </li>)}
          </ul>
        </section>)}
      </div>
    </div>
    {footer && <div className="mf-settings-sidebar__footer">{footer}</div>}
  </nav>;
}

.mf-settings-sidebar { --mf-sidebar-selected: #f5f5f5; --mf-sidebar-hover: #e5e5e5; box-sizing: border-box; display: flex; flex-direction: column; width: 238px; max-width: 100%; min-height: 0; color: #0a0a0a; background: #fafafa; font: 13px/1.4 'Inter Variable', Inter, system-ui, sans-serif; }
.mf-settings-sidebar *, .mf-settings-sidebar *::before, .mf-settings-sidebar *::after { box-sizing: border-box; }
.mf-settings-sidebar__header { flex: none; padding: 21px 20px 20px; }
.mf-settings-sidebar__scroll { min-height: 0; flex: 1; overflow: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: #d4d4d4 transparent; }
.mf-settings-sidebar__body { position: relative; isolation: isolate; min-width: 206px; padding: 0 12px 16px; }
.mf-settings-sidebar__hover { position: absolute; top: 0; left: 0; border-radius: 7px; background: var(--mf-sidebar-hover); pointer-events: none; z-index: -1; }
.mf-settings-sidebar__group + .mf-settings-sidebar__group { margin-top: 20px; }
.mf-settings-sidebar__group-label { margin: 0 0 7px; padding: 0 10px; color: #525252; font: inherit; font-size: 10px; font-weight: 550; line-height: 18px; letter-spacing: .07em; text-transform: uppercase; }
.mf-settings-sidebar__items { list-style: none; padding: 0; margin: 0; }
.mf-settings-sidebar__item + .mf-settings-sidebar__item { margin-top: 3px; }
.mf-settings-sidebar__button { appearance: none; display: flex; align-items: center; gap: 10px; width: 100%; min-height: 35px; margin: 0; padding: 8px 10px; border: 0; border-radius: 7px; background: transparent; color: inherit; text-align: left; font: inherit; line-height: 19px; cursor: pointer; transition: color 160ms ease, background-color 160ms ease; }
.mf-settings-sidebar__button[aria-current=page] { background: var(--mf-sidebar-selected); color: #0a0a0a; font-weight: 550; box-shadow: inset 0 0 0 1px #d4d4d4; }
.mf-settings-sidebar__button:focus-visible { outline: 2px solid #737373; outline-offset: 1px; }
.mf-settings-sidebar__button:disabled { opacity: 1; color: #6b6b6b; cursor: not-allowed; }
.mf-settings-sidebar__icon { display: flex; width: 17px; height: 17px; flex: 0 0 17px; align-items: center; justify-content: center; color: #0a0a0a; }
.mf-settings-sidebar__icon svg { width: 17px; height: 17px; }
.mf-settings-sidebar__button[aria-current=page] .mf-settings-sidebar__icon { color: #0a0a0a; }
.mf-settings-sidebar__label { white-space: nowrap; }
.mf-settings-sidebar__trailing { margin-left: auto; color: #737373; font-size: 10px; white-space: nowrap; }
.mf-settings-sidebar__footer { flex: none; padding: 15px 20px; border-top: 1px solid #e5e5e5; }
@media (prefers-reduced-motion: reduce) { .mf-settings-sidebar__button { transition: none; } }

.mf-settings-sidebar__button:disabled .mf-settings-sidebar__icon { color: inherit; }
